const refs={cli:source('Cisco IOS XE 17.x CLI guide','https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/syst-mgmt/b-system-management/m_cf-cli-basics.html'),files:source('Catalyst 9300 IOS XE 17.15 configuration files','https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9300/software/release/17-15/configuration_guide/sys_mgmt/b_1715_sys_mgmt_9300_cg/managing_configuration_files.html'),merge:source('Cisco configuration replace versus merge','https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/syst-mgmt/b-system-management/m_cm-config-rollback-0.html'),architecture:source('Cisco IOS XE process architecture and CPU troubleshooting','https://www.cisco.com/c/en/us/support/docs/ios-nx-os-software/ios-xe-16/213549-troubleshoot-high-cpu-usage-in-catalyst.html'),cml:source('Cisco CML Catalyst 8000V reference','https://developer.cisco.com/docs/modeling-labs/cat-8000v/')};
const q=(difficulty,testedConcept,question,answer,explanation,options)=>({difficulty,testedConcept,question,answer,explanation,type:options?'multiple-choice':'short-answer',...(options?{options}:{})});
